Given the following code using <b>Map.groupBy()</b>, which fruit objects are stored inside the array returned by `result.get("low")`?
```js
const fruits = [
  { name: "apples", quantity: 300 },
  { name: "bananas", quantity: 500 },
  { name: "oranges", quantity: 200 },
  { name: "kiwi", quantity: 150 }
];
function myCallback({ quantity }) {
  return quantity > 200 ? "ok" : "low";
}
const result = Map.groupBy(fruits, myCallback);
```

In the following <b>JavaScript animation</b> code, what causes the movement of the `#animate` element to stop?
```js
function myMove() {
  let id = null;
  const elem = document.getElementById("animate");
  let pos = 0;
  id = setInterval(frame, 5);
  function frame() {
    if (pos == 350) {
      clearInterval(id);
    } else {
      pos++;
      elem.style.top = pos + "px";
      elem.style.left = pos + "px";
    }
  }
}
```

In the validation function below, if the user enters `"15"` into `#demo`, what will be the content of `#p01` and the value of `#demo` after `myFunction()` finishes?
```js
function myFunction() {
  const message = document.getElementById("p01");
  message.innerHTML = "";
  let x = document.getElementById("demo").value;
  try {
    if (x == "") throw "is empty";
    if (isNaN(x)) throw "is not a number";
    x = Number(x);
    if (x > 10) throw "is too high";
    if (x < 5) throw "is too low";
  } catch (err) {
    message.innerHTML = "Error: " + err + ".";
  } finally {
    document.getElementById("demo").value = "";
  }
}
```

